'use strict';
const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['reviseAsset']);
const { reviseAsset } = api;
assert.strictEqual(typeof reviseAsset, 'function');

const original = { assetId: 'a1', label: 'Old', category: 'Tools', active: true };
const patch = { label: '  New label  ', category: '  Hardware ', active: false };
const result = reviseAsset(original, patch);
assert.deepStrictEqual(result, {
  assetId: 'a1',
  label: 'New label',
  category: 'Hardware',
  active: false
});
assert.notStrictEqual(result, original);
assert.deepStrictEqual(original, { assetId: 'a1', label: 'Old', category: 'Tools', active: true });
assert.deepStrictEqual(patch, { label: '  New label  ', category: '  Hardware ', active: false });
assert.deepStrictEqual(Object.keys(result), ['assetId', 'label', 'category', 'active']);

const emptyResult = reviseAsset(original, {});
assert.deepStrictEqual(emptyResult, original);
assert.notStrictEqual(emptyResult, original);

const inheritedPatch = Object.create({ label: 'Inherited', active: false });
assert.deepStrictEqual(reviseAsset(original, inheritedPatch), original);

const hiddenAsset = {};
Object.defineProperties(hiddenAsset, {
  assetId: { value: 'hidden-1', enumerable: false },
  label: { value: 'Hidden', enumerable: false },
  category: { value: 'Internal', enumerable: false },
  active: { value: true, enumerable: false }
});
assert.deepStrictEqual(reviseAsset(hiddenAsset, { label: ' Visible ' }), {
  assetId: 'hidden-1', label: 'Visible', category: 'Internal', active: true
});

const hiddenPatch = {};
Object.defineProperty(hiddenPatch, 'category', { value: '  Secret  ', enumerable: false });
assert.strictEqual(reviseAsset(original, hiddenPatch).category, 'Secret');

for (const bad of [null, undefined, [], 1, 'x', true]) {
  assert.throws(() => reviseAsset(bad, {}), TypeError);
  assert.throws(() => reviseAsset(original, bad), TypeError);
}

assert.throws(() => reviseAsset(original, { assetId: 'a2' }), TypeError);
assert.throws(() => reviseAsset(original, { extra: 1 }), TypeError);
const symbolPatch = { [Symbol('extra')]: 1 };
assert.throws(() => reviseAsset(original, symbolPatch), TypeError);
const nonEnumerableUnknown = {};
Object.defineProperty(nonEnumerableUnknown, 'extra', { value: 1, enumerable: false });
assert.throws(() => reviseAsset(original, nonEnumerableUnknown), TypeError);

for (const key of ['label', 'category']) {
  assert.throws(() => reviseAsset(original, { [key]: '' }), RangeError);
  assert.throws(() => reviseAsset(original, { [key]: '   ' }), RangeError);
  assert.throws(() => reviseAsset(original, { [key]: 3 }), TypeError);
}
assert.throws(() => reviseAsset(original, { active: 1 }), TypeError);

const invalidAssets = [
  { label: 'x', category: 'y', active: true },
  { assetId: '', label: 'x', category: 'y', active: true },
  { assetId: 'a', label: '', category: 'y', active: true },
  { assetId: 'a', label: 'x', category: '', active: true },
  { assetId: 'a', label: 'x', category: 'y', active: 'yes' },
  { assetId: 'a', label: 'x', category: 'y', active: true, extra: 1 },
  Object.assign({ assetId: 'a', label: 'x', category: 'y', active: true }, { [Symbol('x')]: 1 })
];
for (const asset of invalidAssets) assert.throws(() => reviseAsset(asset, {}), TypeError);

