'use strict';
const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['PartsCatalog']);
const { PartsCatalog } = api;
assert.strictEqual(typeof PartsCatalog, 'function');

assert.throws(() => new PartsCatalog(null), TypeError);
assert.throws(() => new PartsCatalog({}), TypeError);
assert.throws(() => new PartsCatalog([
  { sku: 'x', description: 'One', quantity: 1 },
  { sku: ' x ', description: 'Two', quantity: 2 }
]), Error);

const source = { sku: '  A-1  ', description: 'Bolt', quantity: 0 };
const catalog = new PartsCatalog([source]);
source.description = 'caller mutation';
source.quantity = 99;
assert.deepStrictEqual(catalog.get('A-1'), { sku: 'A-1', description: 'Bolt', quantity: 0 });
assert.deepStrictEqual(catalog.get(' A-1 '), { sku: 'A-1', description: 'Bolt', quantity: 0 });
assert.strictEqual(catalog.get('a-1'), null);

const addedInput = { sku: 'B-2', description: 'Bracket', quantity: 12 };
const added = catalog.add(addedInput);
assert.deepStrictEqual(added, { sku: 'B-2', description: 'Bracket', quantity: 12 });
assert.notStrictEqual(added, addedInput);
added.description = 'changed return';
addedInput.description = 'changed input';
assert.strictEqual(catalog.get('B-2').description, 'Bracket');
assert.throws(() => catalog.add({ sku: ' B-2 ', description: 'Duplicate', quantity: 1 }), Error);

const get1 = catalog.get('B-2');
const get2 = catalog.get('B-2');
assert.notStrictEqual(get1, get2);
get1.quantity = 100;
assert.strictEqual(catalog.get('B-2').quantity, 12);

const list1 = catalog.list();
const list2 = catalog.list();
assert.deepStrictEqual(list1, [
  { sku: 'A-1', description: 'Bolt', quantity: 0 },
  { sku: 'B-2', description: 'Bracket', quantity: 12 }
]);
assert.notStrictEqual(list1, list2);
assert.notStrictEqual(list1[0], list2[0]);
list1.reverse();
list1[0].description = 'mutated';
assert.deepStrictEqual(catalog.list().map(record => record.sku), ['A-1', 'B-2']);
assert.strictEqual(catalog.get('B-2').description, 'Bracket');

const updated = catalog.update(' A-1 ', { description: 'Steel bolt', quantity: 7 });
assert.deepStrictEqual(updated, { sku: 'A-1', description: 'Steel bolt', quantity: 7 });
updated.quantity = 200;
assert.strictEqual(catalog.get('A-1').quantity, 7);
assert.deepStrictEqual(catalog.list().map(record => record.sku), ['A-1', 'B-2']);

const emptyUpdate = catalog.update('A-1', {});
assert.deepStrictEqual(emptyUpdate, { sku: 'A-1', description: 'Steel bolt', quantity: 7 });
assert.notStrictEqual(emptyUpdate, catalog.get('A-1'));
assert.strictEqual(catalog.update('missing', { quantity: 1 }), null);

const hiddenPatch = {};
Object.defineProperty(hiddenPatch, 'quantity', { value: 8, enumerable: false });
assert.strictEqual(catalog.update('A-1', hiddenPatch).quantity, 8);
const symbolPatch = { [Symbol('extra')]: 1 };
assert.throws(() => catalog.update('A-1', symbolPatch), TypeError);
const unknownPatch = {};
Object.defineProperty(unknownPatch, 'extra', { value: 1, enumerable: false });
assert.throws(() => catalog.update('A-1', unknownPatch), TypeError);
assert.throws(() => catalog.update('A-1', { sku: 'C-3' }), TypeError);

for (const record of [
  null,
  [],
  { sku: '', description: 'x', quantity: 0 },
  { sku: '   ', description: 'x', quantity: 0 },
  { sku: 'x', description: '', quantity: 0 },
  { sku: 'x', description: '   ', quantity: 0 },
  { sku: 'x', description: 'x', quantity: -1 },
  { sku: 'x', description: 'x', quantity: 1.5 },
  { sku: 'x', description: 'x', quantity: '1' }
]) assert.throws(() => catalog.add(record), TypeError);

for (const patch of [null, [], 1, { description: '' }, { description: 4 }, { quantity: -1 }, { quantity: 2.5 }]) {
  assert.throws(() => catalog.update('A-1', patch), TypeError);
}
for (const sku of ['', '   ', null, 1, {}]) {
  assert.throws(() => catalog.get(sku), TypeError);
  assert.throws(() => catalog.update(sku, {}), TypeError);
  assert.throws(() => catalog.remove(sku), TypeError);
}
assert.throws(() => catalog.update('missing', { quantity: -1 }), TypeError);

assert.strictEqual(catalog.remove(' B-2 '), true);
assert.strictEqual(catalog.remove('B-2'), false);
assert.strictEqual(catalog.get('B-2'), null);
assert.deepStrictEqual(catalog.list(), [{ sku: 'A-1', description: 'Steel bolt', quantity: 8 }]);

const empty = new PartsCatalog();
assert.deepStrictEqual(empty.list(), []);

